// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate } from '../remotionShim';


export type DropperAnimationProps = Record<string, any>;

const DropperAnimation: React.FC<DropperAnimationProps> = ({
  backgroundColor = "#EBEBE6",
  transparentBackground = false,
  durationInSeconds = 4,
  bottleColor = "#2A2C2E",
  bulbColor = "#1D1E1F",
  dropColor = "#5A8B8C",
  dropCount = 3,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safety variables
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const totalFrames = fps * durationInSeconds;
  
  // Responsive scaling
  const minDimension = Math.min(width, height);
  const masterScale = (minDimension / 1080) * 2.5; 

  // Seamless hover looping: 1 full cycle per duration
  const hoverY = Math.sin((frame / totalFrames) * Math.PI * 2) * 15;

  // Drop timings
  const interval = totalFrames / dropCount;
  const formEnd = Math.max(1, Math.floor(totalFrames * 0.15));
  const stretchPeak = Math.max(formEnd + 1, Math.floor(totalFrames * 0.25));
  const fadeStart = Math.max(stretchPeak + 1, Math.floor(totalFrames * 0.70));
  const fallEnd = Math.max(fadeStart + 1, Math.floor(totalFrames * 0.85));

  const drops = Array.from({ length: dropCount }).map((_, i) => {
    // Offset frame to create a seamless looping sequence for each drop
    const localFrame = (frame + totalFrames - (i * interval)) % totalFrames;

    // Formation phase: drop scales up at the tip
    const scaleDrop = interpolate(localFrame, [0, formEnd], [0, 1], { 
      extrapolateRight: "clamp" 
    });

    // Fall phase: drop detaches and falls down
    const dropY = interpolate(localFrame, [formEnd, fallEnd], [0, 280], { 
      extrapolateLeft: "clamp", 
      extrapolateRight: "clamp" 
    });

    // Stretch phase: drop elongates as it accelerates, then normalizes
    const stretchY = interpolate(localFrame, [formEnd, stretchPeak, fallEnd], [1, 1.4, 1], { 
      extrapolateLeft: "clamp", 
      extrapolateRight: "clamp" 
    });
    const stretchX = interpolate(localFrame, [formEnd, stretchPeak, fallEnd], [1, 0.7, 1], { 
      extrapolateLeft: "clamp", 
      extrapolateRight: "clamp" 
    });

    // Fade phase: dissolves cleanly before the loop resets
    const opacity = interpolate(localFrame, [fadeStart, fallEnd], [1, 0], { 
      extrapolateLeft: "clamp", 
      extrapolateRight: "clamp" 
    });

    const isVisible = localFrame < fallEnd;

    return {
      key: i,
      scaleDrop,
      dropY,
      stretchX,
      stretchY,
      opacity: isVisible ? opacity : 0,
    };
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, display: "flex", justifyContent: "center", alignItems: "center" }}>
      <div style={{ transform: `scale(${masterScale})`, display: "flex", justifyContent: "center", alignItems: "center" }}>
        
        {/* Animated Hover Wrapper */}
        <div style={{ 
          transform: `translateY(${hoverY}px)`, 
          display: "flex", 
          flexDirection: "column", 
          alignItems: "center", 
          position: "relative",
          transition: "none"
        }}>
          
          {/* Bulb */}
          <div style={{
            width: 50,
            height: 60,
            backgroundColor: bulbColor,
            borderRadius: "25px 25px 12px 12px",
            zIndex: 3,
            boxShadow: "inset -8px -4px 10px rgba(0,0,0,0.3)",
            transition: "none"
          }} />

          {/* Cap Ridge */}
          <div style={{
            width: 56,
            height: 18,
            backgroundColor: bottleColor,
            borderRadius: 3,
            zIndex: 4,
            marginTop: -6,
            boxShadow: "0 4px 8px rgba(0,0,0,0.15)",
            transition: "none"
          }} />

          {/* Glass Tube */}
          <div style={{
            width: 14,
            height: 90,
            border: `2px solid ${bottleColor}`,
            borderTop: "none",
            borderRadius: "0 0 7px 7px",
            zIndex: 2,
            position: "relative",
            overflow: "hidden",
            backgroundColor: "rgba(255, 255, 255, 0.2)",
            transition: "none"
          }}>
            {/* Liquid inside the tube */}
            <div style={{
              position: "absolute",
              bottom: 0,
              width: "100%",
              height: "35%",
              backgroundColor: dropColor,
              borderRadius: "0 0 4px 4px",
              transition: "none"
            }} />
            
            {/* Glass reflection highlight */}
            <div style={{
              position: "absolute",
              top: 0,
              left: 0,
              width: "100%",
              height: "100%",
              background: "linear-gradient(90deg, rgba(255,255,255,0.1) 0%, rgba(255,255,255,0.6) 25%, rgba(255,255,255,0) 60%, rgba(255,255,255,0.2) 100%)",
              transition: "none"
            }} />
          </div>

          {/* Drops Container Origin */}
          <div style={{ 
            position: "absolute", 
            top: "100%", 
            left: "50%", 
            width: 0, 
            height: 0, 
            zIndex: 1, // Behind the tube's front edge
            transition: "none"
          }}>
            {drops.map((drop) => (
              <svg
                key={drop.key}
                viewBox="0 0 24 24"
                style={{
                  width: 18,
                  height: 24,
                  position: "absolute",
                  left: -9, // Center horizontally
                  top: -2, // Slight overlap to merge with the tube
                  transformOrigin: "top center",
                  transform: `translateY(${drop.dropY}px) scaleX(${drop.scaleDrop * drop.stretchX}) scaleY(${drop.scaleDrop * drop.stretchY})`,
                  opacity: drop.opacity,
                  fill: dropColor,
                  transition: "none"
                }}
              >
                <path d="M 12 0 C 12 0 4 10 4 16 A 8 8 0 0 0 20 16 C 20 10 12 0 12 0 Z" />
              </svg>
            ))}
          </div>

        </div>
      </div>
    </AbsoluteFill>
  );
};

export default DropperAnimation;